using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Services;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class BankReconciliationTests
{
 class User(bool grant=true):ICurrentUser{public string Email=>"finance@example.local";public int? EmployeeId=>1;public int UserId=>1;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>false;public bool Can(string p)=>p==Perm.PayView||grant&&p==Perm.PayReconcile;}
 static async Task<AppDbContext> Db(){var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.MigrateAsync();await SeedData.InitializeAsync(d,"Admin123!","Demo123!",new DateTime(2026,11,24));return d;}
 static BankReconciliation S(AppDbContext d,bool grant=true){var u=new User(grant);var c=new AppClock(TimeProvider.System);return new(d,u,c,new AuditService(d,u,c));}
 static async Task<(int,int)> Run(AppDbContext d,PayrollStatus status=PayrollStatus.Finalized){var r=new PayrollRun{Year=2030,Month=1,Status=status};d.Add(r);await d.SaveAsync();var l=new PayrollLine{RunId=r.Id,EmployeeId=6,Net=1000,EmployeeCodeSnapshot="TEST"};d.Add(l);await d.SaveAsync();return(r.Id,l.Id);}
 [Fact]public async Task SeparateGrantIsRequiredAndNoDefaultRoleGetsIt(){await using var d=await Db();var(r,l)=await Run(d);await Assert.ThrowsAsync<DomainException>(()=>S(d,false).ResultsAsync(r));await Assert.ThrowsAsync<DomainException>(()=>S(d,false).RecordAsync(r,l,"Paid",1000,"REF","Bank advice"));Assert.DoesNotContain(await d.Set<RolePermission>().ToListAsync(),x=>x.Permission==Perm.PayReconcile);}
 [Fact]public async Task LockedRunAndExactAmountAreRequired(){await using var d=await Db();var(r,l)=await Run(d,PayrollStatus.Draft);await Assert.ThrowsAsync<DomainException>(()=>S(d).RecordAsync(r,l,"Paid",1000,"REF","Advice"));(await d.Set<PayrollRun>().FindAsync(r))!.Status=PayrollStatus.Finalized;await d.SaveAsync();foreach(var o in new[]{"Paid","Returned","Rejected"})await Assert.ThrowsAsync<DomainException>(()=>S(d).RecordAsync(r,l,o,500,"REF","Advice"));await Assert.ThrowsAsync<DomainException>(()=>S(d).RecordAsync(r,l,"Paid",1000,"","Advice"));await Assert.ThrowsAsync<DomainException>(()=>S(d).RecordAsync(r,l+1,"Paid",1000,"REF","Advice"));Assert.Empty(await S(d).ResultsAsync(r));}
 [Fact]public async Task ReturnAndRetryRetainHistoryWithoutPayrollOrAdvanceEffects(){await using var d=await Db();var(r,l)=await Run(d);var s=S(d);await Assert.ThrowsAsync<DomainException>(()=>s.RecordAsync(r,l,"Returned",1000,"NO","No payment"));await s.RecordAsync(r,l,"Rejected",0,"REJECT-1","Rejected advice");await s.RecordAsync(r,l,"Paid",1000,"PAID-1","Successful advice");await Assert.ThrowsAsync<DomainException>(()=>s.RecordAsync(r,l,"Paid",1000,"PAID-2","Duplicate"));await Assert.ThrowsAsync<DomainException>(()=>s.RecordAsync(r,l,"Rejected",0,"R","Not a return"));await s.RecordAsync(r,l,"Returned",1000,"RETURN-1","Return advice");await Assert.ThrowsAsync<DomainException>(()=>s.RecordAsync(r,l,"Paid",1000,"PAID-1","Duplicate reference"));await s.RecordAsync(r,l,"Paid",1000,"PAID-2","Second payment advice");var rows=await s.ResultsAsync(r);Assert.Equal(new[]{1,2,3,4},rows.Select(x=>x.Version));Assert.Equal(PayrollStatus.Finalized,(await d.Set<PayrollRun>().FindAsync(r))!.Status);Assert.Equal(1000,(await d.Set<PayrollLine>().FindAsync(l))!.Net);Assert.Null((await d.Set<PayrollRun>().FindAsync(r))!.PaidAt);}
 [Fact]public async Task EvidenceIsAppendOnlyAndAuditDoesNotCopyReferences(){await using var d=await Db();var(r,l)=await Run(d);await S(d).RecordAsync(r,l,"Paid",1000,"PRIVATE-REFERENCE","Sensitive advice");Assert.DoesNotContain(await d.Set<AuditLog>().ToListAsync(),x=>x.Details.Contains("PRIVATE-REFERENCE"));(await d.Set<PayrollBankResult>().SingleAsync()).Note="Rewrite";await Assert.ThrowsAsync<InvalidOperationException>(()=>d.SaveAsync());d.ChangeTracker.Clear();d.Remove(await d.Set<PayrollBankResult>().SingleAsync());await Assert.ThrowsAsync<InvalidOperationException>(()=>d.SaveAsync());}
}
